import { getGoodsList, addComment, footerPhoneSubs, getAwsS3Data } from '@utils/api.js'
import { dateFormat, verifyEmail, uploadToS3, copyFunc, getSocialShareAPI } from '@utils/index.js'
import dayjs from "dayjs";

export class CommentForm {
    constructor({el}) {
        this.DOM = {
            el: $(el),
            clas: el,
            textarea: $(el).find('.form-textarea'),
            showRelateProduct: $(el).data('show-relate-product') || false, // 是否显示关联产品
            showMyComment: $(el).data('show-my-comment') || false, // 是否展示我的留言模块
            uploadFlag: $(el).data('upload-flag'), // 是否显示上传图片
            upload_require: $(el).data('upload_require'), // 图片是否必须上传
            upload_require_msg: $(el).data('upload_require_msg'), // 图片必须上传提示语
            uploading: $(el).data('uploading'),// 上传中提示语
            upload_exceed_error: $(el).data('upload_exceed_error'), // 图片大小限制提示语
            upload_format_error: $(el).data('upload_format_error'), // 图片格式限制提示语
            hbid: $(el).data('hbid') || '', // 活动id
            title: $(el).data('title') || '', // 活动标题
            mode: $(el).data('mode'), // 提示类型 1: Toast提示 2: 弹窗提示
            share_text: $(el).data('share_text') || '', // 分享文案
            copy_text: $(el).data('copy_text') || '', // 复制成功提示语
        }
        this.s3 = null
        this.init()
    }
    init() {
        this.onEvent()
        if (this.DOM.showRelateProduct == true) {
            this.getGoods()
        }
    }
    async getGoods() {
        try {
            const { data } = await getGoodsList()
            const list = data.map(({ sku, originTitle }) => ({ sku, originTitle })) || [];
            let html = ''
            list.forEach(item => {
                html += `
                    <div class="item" data-id="${item.sku}">${item.originTitle}</div>
                ` 
            })
            $(`${this.DOM.clas} .list`).html(html)
        } catch (error) {
            pushErrorMessage(error);
        }
    }
    checkData() {
        let flag = false
        $('.error').hide()
        // 评论
        $('#comment').removeClass('form-error')
        const comment = $('#comment').val()
        if (comment.trim().length == 0) {
            flag = true
            $('.comment-error').show()
            $('#comment').addClass('form-error')
        }

        // 关联产品
        if (this.DOM.showRelateProduct == true) {
            $('#product').removeClass('form-error')
            const productVal = $('#product').data('id')
            if(!productVal) {
                flag = true
                $('.product-error').show()
                $('#product').addClass('form-error')
            }
        }
        
        // email
        const customerEmail = this.DOM.el.data('customer-email')
        if (!customerEmail) {
            
            $(`${this.DOM.clas} #email`).removeClass('form-error')
            const email = $(`${this.DOM.clas} #email`).val()
            if (email.trim().length == 0 ||  !verifyEmail(email)) {
                flag = true
                $('.email-error').show()
                $(`${this.DOM.clas} #email`).addClass('form-error')
            }

            // subscribe
            $('#checkbox-label').removeClass('form-error')
            const subscribe = $('#subscribe').is(":checked");

            if(!subscribe) {
                flag = true
                $('.subscribe-error').show()
                $('#checkbox-label').addClass('form-error')
            }
        }

        // 图片上传
        if (this.DOM.uploadFlag == true) {
            const uploadImg = $(`${this.DOM.clas} .upload-image`).attr('src')
            if (this.DOM.upload_require == true && !uploadImg) {
                flag = true
                $('.upload-error').text(this.DOM.upload_require_msg).show()
            }
        }
        return flag
    }
    onEvent() {
        const that = this
        $(`${that.DOM.clas} .form-textarea`).bind('input propertychange',function() {
            $(`${that.DOM.clas} .now-number`).text($(this).val().length)
        })

        $(`${that.DOM.clas} .choose`).click(function() {
            $(`${that.DOM.clas} .list`).addClass('data-show')
            const id=$(this).data('id')
            if (id) {
                $(`${that.DOM.clas} .item[data-id="${id}"]`).addClass('selected')
            }
        })

        $(`${that.DOM.clas}`).on('click', '.item', function() {
            $(this).addClass('selected')
            const id = $(this).data('id')
            $(this).siblings().removeClass('selected')
            $(`${that.DOM.clas} .choose`).addClass('has-choosed').text($(this).text()).attr('data-id', id)
            $(`${that.DOM.clas} .choose`).data('id', id)
            $(`${that.DOM.clas} .list`).removeClass('data-show')
            $('#product').removeClass('form-error')
            $('.product-error').hide()
        })

        $(document).click(function(event) {
            const select = $(`${that.DOM.clas} .select`)
            if (!select.is(event.target) && select.has(event.target).length === 0) {
                $(`${that.DOM.clas} .list`).removeClass('data-show')
            }
        })

        // label选择
        $(`${that.DOM.clas}`).on('click', '.label',function() {
            $(this).addClass('selected').siblings().removeClass('selected')
        })

        if (this.DOM.uploadFlag == true) {
            // 图片上传事件处理
            $(`${that.DOM.clas}`).on('change', '.upload-box input', function(e) {
                that.handleImageUpload.call(that, e);
            });

            // 删除已上传图片
            $(`${that.DOM.clas}`).on('click', '.close', function(e) {
                that.handleImageClear.call(that, e);
            });

            // 图片点击放大
            $(`${that.DOM.clas}`).on('click', '.upload-image', function(e) {
                $('#modal-img').attr('src', $(this).attr('src'));
                $('#image-modal').css('display', 'flex');
                $('body').css('overflow', 'hidden');
            })
            // 关闭图片弹窗
            $('#image-modal .close-modal').on('click', function() {
                $('#image-modal').hide();
                $('body').css('overflow', 'auto');
            });
            $('#image-modal').on('click', function() {
                $(this).hide();
                $('body').css('overflow', 'auto');
            });

            // 展示我的留言模块
            if (that.DOM.showMyComment) {
                $('.jky-2th-my-comments').on('click', '.image img', function(e) {
                    $('#modal-img').attr('src', $(this).attr('src'));
                    $('#image-modal').css('display', 'flex');
                    $('body').css('overflow', 'hidden');
                })
            }
        }

        // 数据提交
        $('.submit-button').on('click',async function(e) {
            that.handleSubmit.call(that, e);
        })

        // 弹窗提示关闭
        $(`.success-modal`).on('click', '.close-modal', function(e) {
            $(`.success-modal`).hide()
            $('body').css('overflow', 'auto');
        })

        // 分享
        $(`.success-modal`).on('click', '.share-button', function(e) {
            e.preventDefault()
            const type = $(this).data('type');
            that.handleShare.call(that, type);
        })
    }

    // 图片上传
    async handleImageUpload(e){
        const that = this;
        const files = e.target.files;
        if (!files.length) return;
        const file = files[0];
        // 检查文件类型
        if (!file.type.match('image.*')) {
            pushErrorMessage(that.DOM.upload_format_error);
            e.target.value = null;
            return;
        }
        if (file.size > 10 * 1024 * 1024) {
            pushErrorMessage(that.DOM.upload_exceed_error);
            e.target.value = null;
            return;
        }

        $(`${that.DOM.clas} .upload-box`).addClass('uploading');
        $(`${that.DOM.clas} .upload-box input`).attr('disabled', true );
        $(`${that.DOM.clas} .upload-error`).text(that.DOM.uploading).show();

        let type = file.name.split(".");
        type = type[type.length - 1].toLowerCase();
        const info = await getAwsS3Data();
        uploadToS3({file, filename: `user-comments/${new Date().getTime()}.${type}`}, info.data)
        .then((s3) => {
            that.s3 = s3;
            $(`${that.DOM.clas} .upload-image`).attr('src', s3.Location);
            $(`${that.DOM.clas} .image`).show();
            $(`${that.DOM.clas} .upload-box`).hide();
        }).finally(() => {
            $(`${that.DOM.clas} .upload-error`).text(that.DOM.upload_require_msg).hide();
            $(`${that.DOM.clas} .upload-box`).removeClass('uploading');
            $(`${that.DOM.clas} .upload-box input`).attr('disabled', false);
        })
    }

    // 图片删除
    async handleImageClear(e) {
        const that = this;
        e.preventDefault();
        e.stopPropagation();
        const info = await getAwsS3Data();
        let { access_key_id, secret_access_key, session_token, region, bucket } = info.data;
        let s3Client = new window.AWS.S3({ accessKeyId: access_key_id, secretAccessKey: secret_access_key, sessionToken: session_token, region });
        await s3Client.deleteObject({
            Bucket: bucket,
            Key: that.s3.key
        })
        that.s3 = null;
        $(`${that.DOM.clas} .image`).hide();
        $(`${that.DOM.clas} .upload-image`).attr('src', '');
        $(`${that.DOM.clas} .upload-box`).show();
        $(`${that.DOM.clas} .upload-box input`).val('');
    }

    // 数据提交
    async handleSubmit(e) {
        const that = this;
        e.preventDefault()
        const flag = that.checkData()
        if(!flag) {
            const email = that.DOM.el.data('customer-email')
            const successful = that.DOM.el.data('successful')
            const fileUrl = $(`${that.DOM.clas} .upload-image`).attr('src') || ''
            const query = {
                email: email ? email : $(`${that.DOM.clas} #email`).val().trim(),
                dataId: $('#product').data('id'),
                comment: $('#comment').val().trim(),
                activeNum: that.DOM.hbid,
                tagName: $(`${this.DOM.clas} .label.selected`).data('label'),
                fileUrl,
            }
            try {
                await addComment(query)
                const cr = pageInfo.cr
                // 展示我的留言模块
                if (that.DOM.showMyComment) {
                    $('.jky-2th-my-comments .date').html(dayjs(new Date().getTime()).format(dateFormat(cr)))
                    $('.jky-2th-my-comments .info').text($('#comment').val().trim())
                    if (fileUrl) {
                        $('.jky-2th-my-comments .image img').attr('src', $(`${that.DOM.clas} .upload-image`).attr('src')).show()
                    } else {
                        $('.jky-2th-my-comments .image img').hide()
                    }
                    $('.jky-2th-my-comments').show()
                }
                
                $('#comment').val('')
                $(`${that.DOM.clas} .now-number`).text('0')
                const customerEmail = that.DOM.el.data('customer-email')
                if (customerEmail) return false
                const subscribeParams = {
                    tags: 'Activity-Subscribe',
                    email: query.email
                }
                await footerPhoneSubs(subscribeParams)
                // 图片删除
                that.s3 = null;
                $(`${that.DOM.clas} .image`).hide();
                $(`${that.DOM.clas} .upload-image`).attr('src', '');
                $(`${that.DOM.clas} .upload-box`).show();
                $(`${that.DOM.clas} .upload-box input`).val('');
                $(`${this.DOM.clas} .label.selected`).removeClass('selected')

                // 判断当前是哪种类型
                if (that.DOM.mode == 1) {
                    pushSuccessMessage(successful)
                } else {
                    $(`.success-modal`).show()
                    $('body').css('overflow', 'hidden');
                }
            } catch (error) {
                pushErrorMessage(error.message)
            }
        }
    }

    // 分享
    handleShare(type) {
        const that = this;
        const content = that.DOM.share_text
        const url = getSocialShareAPI(type, content)
        window.open(url, '_blank')
    }
}