import './index.less'
import jkyNav from '../../common/components/jky-nav'
import { CommentForm } from './sections/form/index'
import { Comments } from '../jackery-12th-anniversary/sections/jky-12th-comments/index'
import {RegularBanner} from '../five-kwh-market/sections/five-kwh-banner/index'

document.addEventListener('DOMContentLoaded', () => {
   new RegularBanner(document.querySelector('.five-kwh-banner .swiper-container'))
   jkyNav()
   new CommentForm({el: '.jky-12th-form'})
   new Comments()

   // 渐变出现
   const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // 元素进入视窗,触发动画
            entry.target.classList.add('jky-up-animation');
          }
      });
  });

  // 开始观察目标元素
  const slideups = document.querySelectorAll('.jky-up')
  if (slideups && slideups.length) {
      slideups.forEach(item => {
          observer.observe(item); 
      })
  }
})